"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9721],{9741(e){e.exports=JSON.parse('{"title":"\ube0c\ub77c\uc6b0\uc800\uc758 \uce90\uc2f1\uc740 \uc5b4\ub5bb\uac8c \uc9c4\ud654\ud588\ub294\uac00","date":"2025-01-24","coverUrl":"/kudzu-based-bench/assets/notion/a50b47cbe3963b7f.png","html":"<h2 data-notion-block-id=\\"17ee548d-8a8e-803c-aa8e-d0f2f4507775\\" id=\\"17ee548d-8a8e-803c-aa8e-d0f2f4507775\\">\ube0c\ub77c\uc6b0\uc800\uc758 \uce90\uc2f1\uc740 \uc5b4\ub5bb\uac8c \uc9c4\ud654\ud588\ub294\uac00</h2><a href=\\"https://addyosmani.com/blog/double-keyed-caching/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://addyosmani.com/blog/double-keyed-caching/</a><p data-notion-block-id=\\"17ee548d-8a8e-804a-bf26-eee7e18e09bd\\">\uae30\uc874\uc758 \ube0c\ub77c\uc6b0\uc800\uc758 \uce90\uc2f1 \ubc29\uc2dd\uc774 \ubcf4\uc548 \ubb38\uc81c\ub85c \uc778\ud574 \uce90\uc2f1 \ubc29\uc2dd\uc744 \ubc14\uafb8\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc5b4\ub5bb\uac8c \ubc14\ub00c\uc5c8\ub294\uc9c0, \uc5b4\ub5a4 \uc601\ud5a5\uc744 \ub07c\ucce4\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\uac00 \uce90\uc2f1 \uc804\ub7b5\uc5d0 \ub300\ud574 \uc5b4\ub5bb\uac8c \ubc14\ub00c\uc5b4\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ubbc0\ub85c, \uaf2d \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-80f4-8702-c4232a123df9\\" id=\\"17ee548d-8a8e-80f4-8702-c4232a123df9\\">React Native 5\ub144 \uc0ac\uc6a9 \ub9ac\uc5bc \ud6c4\uae30</h2><a href=\\"https://shopifyengineering.myshopify.com/blogs/engineering/five-years-of-react-native-at-shopify\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shopifyengineering.myshopify.com/blogs/engineering/five-years-of-react-native-at-shopify</a><p data-notion-block-id=\\"17ee548d-8a8e-8094-bbee-e2dd653fe8c6\\">Shopify\uc5d0\uc11c 5\ub144\ub3d9\uc548 \ubaa8\ub4e0 \uc571\uc744 RN\uc73c\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \ub9c8\uce58\uba74\uc11c \ub290\ub080 \uc810\ub4e4\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. RN\uc5d0 New Architecture\uacfc Expo\uc758 \ubc1c\uc804\uc73c\ub85c \ub354 \uc8fc\ubaa9\ud560\ub9cc\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub807\uae30\uc5d0 \uc5b4\ub5a4 \uc810\uc774 \uc88b\uc740\uc9c0, \uc8fc\uc758\ud574\uc57c \ud558\ub294\uc9c0 \uc774 \uae00\uc5d0\uc11c \ud655\uc778\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-8036-ab93-ebb9cc49211c\\" id=\\"17ee548d-8a8e-8036-ab93-ebb9cc49211c\\">Lighthouse \uc810\uc218\uac00 \uc815\ub9d0 UX\uc640 \uad00\ub828 \uc788\uc744\uae4c?</h2><a href=\\"https://debugbear.com/blog/poor-performance-score-good-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://debugbear.com/blog/poor-performance-score-good-performance</a><p data-notion-block-id=\\"17ee548d-8a8e-80ea-91da-c9cf2563b093\\">Lighthouse\uc758 \ud070 \ubb38\uc81c\ub294 \ub85c\uceec\uc5d0\uc11c \uc2dc\ubbac\ub808\uc774\uc158 \ud55c \uacb0\uacfc\uc774\uace0, \uc2e4\uc81c \ud06c\ub864\ub7ec \ubd07\uc774\ub098 \uc2e4\uc81c \uc0ac\uc6a9\uc790 \ud658\uacbd\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \uc65c Lighthouse \uc810\uc218\ub9cc\uc774 \uc804\ubd80\uac00 \uc544\ub2d8\uc744 \uc124\uba85\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc774\uc9c0\ub9cc, \uc5ec\ub7ec \ub370\uc774\ud130\ub97c \uce21\uc815\ud574\uc11c \ud310\ub2e8\ud574\uc57c \ud568\uc744 \ucda9\ubd84\ud788 \uc124\uba85\ud569\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/164e548d-8a8e-80b6-83ab-e98e54c0407f#168e548d-8a8e-8091-bda3-f467a3d84e84\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \uc791\uc5c5\uc744 \uc5b4\ud544\ud574\uc57c \ud558\ub2c8\uae4c\uc694</a>.</p><h2 data-notion-block-id=\\"182e548d-8a8e-80d5-a404-ce95e2facb12\\" id=\\"182e548d-8a8e-80d5-a404-ce95e2facb12\\">\ubc88\ub4e4\ub7ec\ub97c \ube4c\ub4dc \uc2dc\uc2a4\ud15c \uad00\uc810\uc73c\ub85c \ubd84\uc11d\ud558\uae30</h2><a href=\\"https://github.com/orgs/web-infra-dev/discussions/24\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/orgs/web-infra-dev/discussions/24</a><p data-notion-block-id=\\"182e548d-8a8e-80b1-b5ec-da43164a1f19\\">\ube4c\ub4dc \uc2dc\uc2a4\ud15c\uc774 \uc5b4\ub5bb\uac8c \uad6c\uc131\ub418\uc5b4 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 JS\uc758 \ubc88\ub4e4\ub7ec \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \ube4c\ub4dc \uc2dc\uc2a4\ud15c \uad6c\uc131 \uce21\uba74\uc5d0\uc11c \ubc14\ub77c\ubd24\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcfc \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Turbopack\uc5d0\uc11c \uc5b4\ub5a4 \uac1c\ub150\uc744 \ud1b5\ud574 \ubc88\ub4e4\ub9c1 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824\uace0 \ud558\ub294\uc9c0 \uc798 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"185e548d-8a8e-8094-b124-d78e8553fadf\\" id=\\"185e548d-8a8e-8094-b124-d78e8553fadf\\">Core Web Vitals \uc9c0\uc218\ub97c \ub118\uc5b4\uc11c \uc0dd\uac01\ud558\uae30</h2><a href=\\"https://www.youtube.com/watch?v=8Unbv5MUQq0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=8Unbv5MUQq0</a><p data-notion-block-id=\\"185e548d-8a8e-80b9-9655-ca3b0201a493\\">\uc131\ub2a5 \uce21\uc815\uc744 \ud558\uac8c \ub418\uba74 Core Web Vitals \uc810\uc218\ub97c \ubc14\ud0d5\uc73c\ub85c \uc0dd\uac01\ud558\uace0, \uc5b4\ub5bb\uac8c \ud574\uc57c \uc810\uc218\ub97c \ub9ce\uc774 \uc5bb\uc744 \uc218 \uc788\uc744\uc9c0 \uace0\ubbfc\ud558\ub294 \uac83\uc73c\ub85c \ucd9c\ubc1c\ud558\uac8c \ub429\ub2c8\ub2e4. \ubc1c\ud45c\uc5d0\uc11c\ub294 Core Web Vitals \uc810\uc218 \ub4a4\uc5d0, \ud639\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\ub294 \uc131\ub2a5 \ucd5c\uc801\ud654 \uc694\uc18c\ub4e4\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uba87 \uac00\uc9c0 \uc694\uc18c\ub294 \uc790\uc2e0\uc774 \ub9cc\ub4dc\ub294 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc758 \ub0b4\uc6a9\uacfc \uc5f0\uad00\uc9c0\uc5b4\uc57c \ud560 \uc218\ub3c4 \uc788\uc73c\ubbc0\ub85c, \uc798 \uc870\ud569\ud558\ub294\uac8c \uc911\uc694\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-80ca-a473-f173d70c0430\\" id=\\"17ee548d-8a8e-80ca-a473-f173d70c0430\\"><code>navigate(-1)</code>\uc740 \uc633\uc740 \uad6c\ud604\uc77c\uae4c</h2><a href=\\"https://programmingarehard.com/2025/01/13/maybe-dont-navigate-1.html/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://programmingarehard.com/2025/01/13/maybe-dont-navigate-1.html/</a><p data-notion-block-id=\\"17ee548d-8a8e-80df-9140-c911293ba097\\">\ubc31 \ub9c1\ud06c\ub97c <code>navigate(-1)</code>\ub85c \uad6c\ud604\ud558\ub294 \ubaa8\uc2b5\uc774 \ub9ce\uc740\ub370, \uc774 \uad6c\ud604\uc774 \uc0c1\ud669\uc5d0 \ub530\ub77c \uc798\ubabb\ub418\uc5c8\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-80c0-b188-eea2dec83051\\" id=\\"17ee548d-8a8e-80c0-b188-eea2dec83051\\"><code>useActionState</code>\uc5d0\uc11c type safe \uc9c0\ud0a4\uae30</h2><a href=\\"https://www.typeonce.dev/article/make-form-data-and-input-names-type-safe-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.typeonce.dev/article/make-form-data-and-input-names-type-safe-in-react</a><p data-notion-block-id=\\"17ee548d-8a8e-800e-967f-ca57d028c550\\">React 19\uc5d0\uc11c\ub294 FormData\ub97c \uc27d\uac8c \ub2e4\ub8f0 \uc218 \uc788\ub294 <code>useActionState</code>\uc744 \ucd94\uac00\ud588\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <code>react-hook-form</code>\uacfc \uac19\uc740 \ubd80\uac00 \uae30\ub2a5\uc774 \ubd80\uc871\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 TypeScript\ub97c \ud65c\uc6a9\ud574\uc11c type-safe\ud558\uac8c <code>useActionState</code>\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-80c3-a1e2-c6d80e7b2221\\" id=\\"17ee548d-8a8e-80c3-a1e2-c6d80e7b2221\\">React\uc758 <code>&#x3C;ViewTransition></code>\uc18c\uac1c</h2><a href=\\"https://motion.dev/blog/reacts-experimental-view-transition-api\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://motion.dev/blog/reacts-experimental-view-transition-api</a><p data-notion-block-id=\\"17ee548d-8a8e-80d8-ac9a-e41d8e1be79f\\">View Transition\uc744 React\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d <code>&#x3C;ViewTransition></code>\uac00 \ucd94\uac00\ub420 \uc608\uc815\uc785\ub2c8\ub2e4. <code>&#x3C;ViewTransition></code>\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"185e548d-8a8e-80c0-b9a5-c70ec6a35222\\" id=\\"185e548d-8a8e-80c0-b9a5-c70ec6a35222\\">Micro Frontends, Server Components\ub294 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824 \ud588\ub294\uac00</h2><a href=\\"https://webthesis.biblio.polito.it/31061/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webthesis.biblio.polito.it/31061/</a><p data-notion-block-id=\\"185e548d-8a8e-8067-bae0-d9dfdf1d8ac3\\">Micro Frontends\uc640 Server Components\uac00 \uc5b4\ub5a4 \ub9e5\ub77d\uc5d0\uc11c \ub098\uc654\ub294\uc9c0, \uc5b4\ub5a4 \uc7a5\ub2e8\uc774 \uc788\ub294\uc9c0\uc640 \ud604\uc7ac \ub098\uc628 \uad6c\ud604\uccb4\ub97c \uc18c\uac1c\ud558\ub294 \ub17c\ubb38\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uad6c\ud604\uccb4\ub97c \ub2e4\ub8e8\uc9c0\ub294 \uc54a\uaca0\uc9c0\ub9cc, \ud604\uc7ac \uc5b4\ub5bb\uac8c \uae30\uc220\uc774 \ud758\ub7ec\uac00\ub294\uc9c0\uc5d0 \ub300\ud574 \uc0b4\ud3b4\ubcf4\uae30 \uc88b\uc740 \ub17c\ubb38\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ee548d-8a8e-8006-ba30-fc20a932c3a8\\" id=\\"17ee548d-8a8e-8006-ba30-fc20a932c3a8\\">Node.js\uc5d0\uc11c TypeScript\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \uadf8\uc804\uc5d0</h2><a href=\\"https://satanacchio.hashnode.dev/everything-you-need-to-know-about-nodejs-type-stripping\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://satanacchio.hashnode.dev/everything-you-need-to-know-about-nodejs-type-stripping</a><p data-notion-block-id=\\"17ee548d-8a8e-8092-85d3-fa6d86df2218\\">Node.js\uc5d0\uc11c <a href=\\"https://ones-to-watch.ethansup.net/news/post/156e548d-8a8e-8024-aec1-fd27c897c295#159e548d-8a8e-806c-8a0e-c930968a469b\\">ts-blank-space \ub85c\uc9c1</a> \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e0 \ub124\uc774\ud2f0\ube0c TypeScript \uc9c0\uc6d0\uc744 \uc0ac\uc6a9\ud558\uae30 \uc804\uc5d0 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc744 \uc124\uba85\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"182e548d-8a8e-80d4-84c6-e6737eb39a18\\" id=\\"182e548d-8a8e-80d4-84c6-e6737eb39a18\\">\uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc811\uadfc\uc131\uc744 \uace0\ub824\ud574\uc57c \ud558\ub294\uac00</h2><a href=\\"https://martijnhols.nl/blog/accessibility-essentials-every-front-end-developer-should-know\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://martijnhols.nl/blog/accessibility-essentials-every-front-end-developer-should-know</a><p data-notion-block-id=\\"182e548d-8a8e-800c-a565-cd9eb8af1589\\">\uac04\ub2e8\ud558\uac8c \uc811\uadfc\uc131\uc744 \uad6c\ud604\ud558\uace0\uc790 \ud560 \ub54c \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc0b4\ud3b4\ubd10\uc57c\ud558\ub294\uc9c0 \uc18c\uac1c\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uc811\uadfc\uc131\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc811\uadfc\uc131\uc744 \ub192\uc774\ub294 \uc791\uc5c5\uc744 \uc2dc\uc791\ud560 \ub54c \uc88b\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"182e548d-8a8e-80a2-8011-f49a06e5cd59\\" id=\\"182e548d-8a8e-80a2-8011-f49a06e5cd59\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://2ality.com/2025/01/import-attributes.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2ality.com/2025/01/import-attributes.html</a><a href=\\"https://www.trevorlasn.com/blog/node-async-local-storage\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.trevorlasn.com/blog/node-async-local-storage</a><p data-notion-block-id=\\"182e548d-8a8e-8043-81f6-fb0ef7ded85d\\">\ube44\uad50\uc801 \ucd5c\uadfc\uc5d0 \uad6c\ud604\ub41c <code>import \u2026 with {}</code>\uad6c\ubb38\uc744 \uc18c\uac1c\ud558\ub294 \uae00, Node.js\uc758 <code>AsyncLocalStorage</code>\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"182e548d-8a8e-805f-86a8-cc43c6550890\\" id=\\"182e548d-8a8e-805f-86a8-cc43c6550890\\">Yjs\ub97c \uc27d\uac8c \ubc30\uc6b0\uae30</h2><a href=\\"https://learn.yjs.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://learn.yjs.dev/</a><p data-notion-block-id=\\"182e548d-8a8e-8064-bcd5-fa41e1c79850\\">Yjs\ub97c \uc0c1\ud638\uc791\uc6a9 UI\uacfc \ud568\uaed8 \ubc30\uc6b8 \uc218 \uc788\ub294 \uc790\ub8cc\uc785\ub2c8\ub2e4.</p>"}')}}]);